#!/usr/bin/env node
/**
 * Post Sterling Intelligence Briefing to Telegram
 * 
 * Usage:
 *   TELEGRAM_BOT_TOKEN=xxx TELEGRAM_CHAT_ID=yyy node post-to-telegram.js
 * 
 * Or set environment variables in your shell profile
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// Configuration
const BOT_TOKEN = process.env.TELEGRAM_BOT_TOKEN;
const CHAT_ID = process.env.TELEGRAM_CHAT_ID;
const SUMMARY_FILE = path.join(__dirname, 'telegram-summary.txt');

// Validation
if (!BOT_TOKEN) {
  console.error('❌ Error: TELEGRAM_BOT_TOKEN environment variable not set');
  process.exit(1);
}

if (!CHAT_ID) {
  console.error('❌ Error: TELEGRAM_CHAT_ID environment variable not set');
  process.exit(1);
}

// Read summary file
let message;
try {
  message = fs.readFileSync(SUMMARY_FILE, 'utf8');
  console.log(`📄 Loaded summary (${message.length} bytes)`);
} catch (err) {
  console.error(`❌ Error reading ${SUMMARY_FILE}:`, err.message);
  process.exit(1);
}

// Prepare request
const payload = JSON.stringify({
  chat_id: CHAT_ID,
  text: message,
  parse_mode: 'HTML',
  disable_web_page_preview: true
});

const options = {
  hostname: 'api.telegram.org',
  port: 443,
  path: `/bot${BOT_TOKEN}/sendMessage`,
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

// Send request
console.log('📤 Posting to Telegram...');

const req = https.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    const response = JSON.parse(data);

    if (res.statusCode === 200 && response.ok) {
      console.log('✅ Successfully posted to Telegram!');
      console.log(`   Message ID: ${response.result.message_id}`);
      console.log(`   Chat: ${response.result.chat.id}`);
      console.log(`   Date: ${new Date(response.result.date * 1000).toISOString()}`);
      process.exit(0);
    } else {
      console.error('❌ Telegram API error:');
      console.error(`   Status: ${res.statusCode}`);
      console.error(`   Response: ${data}`);
      process.exit(1);
    }
  });
});

req.on('error', (err) => {
  console.error('❌ Request error:', err.message);
  process.exit(1);
});

req.write(payload);
req.end();

