#!/usr/bin/env node
/**
 * Post Sterling Briefing to Telegram from Event Handler
 * 
 * This script is designed to be called by the event handler after a Sterling
 * briefing job completes. It reads the telegram-summary.txt from the job's
 * logs directory and posts it to Telegram.
 * 
 * Usage:
 *   node post-briefing-from-event-handler.js <job-id>
 * 
 * Environment variables required:
 *   TELEGRAM_BOT_TOKEN - Bot token from @BotFather
 *   TELEGRAM_CHAT_ID - Chat ID to send message to
 */

const fs = require('fs');
const path = require('path');

// Get job ID from command line
const jobId = process.argv[2];
if (!jobId) {
  console.error('❌ Error: Job ID required');
  console.error('Usage: node post-briefing-from-event-handler.js <job-id>');
  process.exit(1);
}

// Validate environment variables
const BOT_TOKEN = process.env.TELEGRAM_BOT_TOKEN;
const CHAT_ID = process.env.TELEGRAM_CHAT_ID;

if (!BOT_TOKEN || !CHAT_ID) {
  console.error('❌ Error: TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID required');
  process.exit(1);
}

// Try to load the telegram summary from the job's logs
const summaryPath = path.join(__dirname, '..', 'logs', jobId, 'telegram-summary.txt');
if (!fs.existsSync(summaryPath)) {
  console.error(`❌ Error: Telegram summary not found at ${summaryPath}`);
  process.exit(1);
}

const message = fs.readFileSync(summaryPath, 'utf8');
console.log(`📄 Loaded summary from ${summaryPath} (${message.length} bytes)`);

// Use the event handler's telegram module if available
const telegramToolPath = path.join(__dirname, '..', 'event_handler', 'tools', 'telegram.js');
if (fs.existsSync(telegramToolPath)) {
  console.log('📤 Posting via event handler telegram module...');
  const { sendMessage } = require(telegramToolPath);
  sendMessage(BOT_TOKEN, CHAT_ID, message, { disablePreview: true })
    .then((result) => {
      console.log('✅ Successfully posted to Telegram!');
      console.log(`   Message ID: ${result.message_id}`);
      console.log(`   Chat: ${result.chat.id}`);
      console.log(`   Date: ${new Date(result.date * 1000).toISOString()}`);
    })
    .catch((err) => {
      console.error('❌ Failed to post to Telegram:', err.message);
      process.exit(1);
    });
} else {
  // Fallback to direct API call
  console.log('📤 Posting via direct Telegram API call...');
  const https = require('https');

  const payload = JSON.stringify({
    chat_id: CHAT_ID,
    text: message,
    parse_mode: 'HTML',
    disable_web_page_preview: true
  });

  const options = {
    hostname: 'api.telegram.org',
    port: 443,
    path: `/bot${BOT_TOKEN}/sendMessage`,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload)
    }
  };

  const req = https.request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      try {
        const response = JSON.parse(data);

        if (res.statusCode === 200 && response.ok) {
          console.log('✅ Successfully posted to Telegram!');
          console.log(`   Message ID: ${response.result.message_id}`);
          console.log(`   Chat: ${response.result.chat.id}`);
          console.log(`   Date: ${new Date(response.result.date * 1000).toISOString()}`);
        } else {
          console.error('❌ Telegram API error:');
          console.error(`   Status: ${res.statusCode}`);
          console.error(`   Response: ${data}`);
          process.exit(1);
        }
      } catch (err) {
        console.error('❌ Failed to parse response:', err.message);
        process.exit(1);
      }
    });
  });

  req.on('error', (err) => {
    console.error('❌ Request error:', err.message);
    process.exit(1);
  });

  req.write(payload);
  req.end();
}
